function validateState(s){if(!s||!Array.isArray(s.exams)||!Array.isArray(s.pending)||!Array.isArray(s.records)||!Number.isSafeInteger(s.next)||s.next<1)throw Error('Copia incompatible.');const ids=new Set(),codes=new Set();for(const e of s.exams){if(typeof e.id!=='string'||ids.has(e.id)||typeof e.title!=='string'||!Object.keys(kinds).every(k=>Array.isArray(e.materials?.[k])&&e.materials[k].every(f=>typeof f.name==='string'&&typeof f.data==='string'&&/^data:[^,]*;base64,/.test(f.data))))throw Error('Materiales inválidos en copia.');if(e.scanSource)validateScanSource(e.scanSource);if(e.scanConfig){const c=e.scanConfig;if(!e.scanSource||c.hash!==e.scanSource.hash||!['ordered','printed'].includes(c.mode)||!Array.isArray(c.ranges))throw Error('Separación del documento inválida en copia.');if(c.mode==='ordered')anonymousBatchGroups(e.scanSource.count,c.ranges,[],c.hash);else splitRanges(e.scanSource.count,c.ranges);}if(e.correctionType!==undefined&&!['exam','task'].includes(e.correctionType))throw Error('Tipo de corrección inválido.');if(e.plan)validatePlan(e.plan);if(e.numbering){numbering(e.numbering);if(e.createdExam)validateExam(e.createdExam)}ids.add(e.id)}for(const p of [...s.pending,...s.records]){if(!belongs(s.exams.find(e=>e.id===p.examId),p.code)||codes.has(p.code)||!s.exams.find(e=>e.id===p.examId)?.plan||(p.code.startsWith('EX-')&&Number(p.code.slice(3))>=s.next))throw Error('Código inválido en copia.');codes.add(p.code);if(p.batchSource){validateBatchSource(p.batchSource);if(!p.code.startsWith('EX-')||p.photos?.length!==batchPages(p.batchSource).length)throw Error('Referencia de PDF sin código incoherente.')}}for(const p of s.pending){if(typeof p.requestId!=='string'||!Array.isArray(p.photos)||!p.photos.length||p.photos.length>20||p.photos.some(x=>typeof x!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(x)))throw Error('Fotos inválidas en copia.')}for(const r of s.records){if(r.photos!==undefined){if(!Array.isArray(r.photos)||!r.photos.length||r.photos.length>20||r.photos.some(x=>typeof x!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(x)))throw Error('Imágenes de corrección inválidas');validateNotes(r.result.notes,r.photos.length,r.result.items)}const g=grade(r.result,s.exams.find(e=>e.id===r.examId));if(['final','total','penalty'].some(k=>g[k]!==r.grade[k]))throw Error('Nota incoherente en copia.');officialGrade(r.grade)}validateClasses(s.classes||[]);return migrateLibrary(s)}
