function renderFolderCards(){const id=libAtRoot?null:$('libraryFolder').value,query=libAtRoot?$('libFolderSearch').value:'';const rows=browseFolders(repositoryView(state.library,libraryView),id,query);$('libFolderLabel').textContent=libAtRoot?(query.trim()?'Resultados de carpetas':'Tus carpetas'):'Subcarpetas';$('libFolderCount').textContent=rows.length+' '+(rows.length===1?'carpeta':'carpetas');const list=$('folderOverview');list.replaceChildren();for(const f of rows){const b=document.createElement('button');b.type='button';b.className='lib-folder '+(f.pau?'lib-pau':'lib-topic');b.innerHTML=`<span class="lib-folder-icon">${libIcon(true)}</span><span class="lib-folder-main"><strong>${esc(query.trim()?f.path:f.title)}</strong><small>${f.total} ${f.total===1?'documento':'documentos'}${f.children?' · '+f.children+' subcarp.':''}</small></span><span aria-hidden="true" class="lib-chevron">›</span>`;b.onclick=()=>navigateLibrary(f.id);list.append(b)}if(!rows.length){const p=document.createElement('p');p.className='lib-empty';p.textContent=query.trim()?'No se encontraron carpetas.':libAtRoot?'Crea tu primera carpeta.':'No hay subcarpetas. Puedes añadirlas en Gestionar carpetas.';list.append(p)}}
