function renderLibraryFiles(){const folder=libAtRoot?null:state.library.find(f=>f.id===$('libraryFolder').value);if(!folder)return;const allowed=repositoryKinds[libraryView],visible=folder.files.filter(f=>allowed.includes(f.kind));const cat=$('libCategories');cat.replaceChildren();for(const kind of ['all',...allowed]){const n=kind==='all'?visible.length:visible.filter(f=>f.kind===kind).length;const b=document.createElement('button');b.className='lib-category lib-'+kind;b.setAttribute('aria-pressed',String(kind===libKind));b.innerHTML=`<span>${esc(kind==='all'?'Todos los documentos':libShort[kind])}</span><strong>${n}</strong>`;b.onclick=()=>{libKind=kind;renderLibraryFiles();cat.querySelector('[aria-pressed="true"]')?.focus({preventScroll:true})};cat.append(b)}const rows=browseFiles(folder,libKind,$('librarySearch').value).filter(e=>allowed.includes(e.file.kind));$('libDocCount').textContent=rows.length+' de '+visible.length;const dest=state.library.filter(f=>f.id!==folder.id);let previous='';$('libraryFiles').innerHTML=rows.map(({file:f,index:i})=>{const heading=f.kind!==previous?`<h3 class="lib-group lib-${f.kind}">${esc(libShort[f.kind])}</h3>`:'';previous=f.kind;return heading+`<div class="lib-file"><div class="lib-file-line"><span class="lib-file-icon lib-${f.kind}">${libIcon()}</span><div class="lib-file-name"><b>${esc(f.name)}</b><small>${esc(materialLabels[f.kind])}</small></div><button class="secondary lib-download" data-libget="${i}" aria-label="Descargar ${esc(f.name)}">Descargar</button></div><details class="lib-file-tools"><summary>Gestionar archivo</summary><label>Tipo de material<select data-reclass="${i}">${Object.entries(materialLabels).map(([k,label])=>`<option value="${k}" ${f.kind===k?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${dest.length?`<label>Carpeta de destino<select data-movetarget="${i}"><option value="">Selecciona destino</option>${dest.map(d=>`<option value="${esc(d.id)}">${esc(folderPath(state.library,d.id))}</option>`).join('')}</select></label><button class="secondary" data-libmove="${i}">Mover archivo</button>`:''}<button class="secondary danger" data-libdel="${i}">Quitar del repositorio</button></details></div>`}).join('')||'<p class="lib-empty">'+(visible.length?'No hay documentos que coincidan con el filtro.':'Esta carpeta está vacía. Pulsa Añadir materiales para empezar.')+'</p>'}
$('libHome').onclick=()=>navigateLibrary(null);$('libNewShortcut').onclick=()=>{$('libManage').open=true;$('newFolderTitle').focus();};$('libUploadShortcut').onclick=()=>{$('quickLibrary').open=true;$('quickLibrary').scrollIntoView({block:'start'});$('referenceKind').focus({preventScroll:true});};$('libFolderSearch').oninput=renderFolderCards;$('librarySearch').oninput=renderLibraryFiles;
$('newFolder').onclick=run(async()=>{const next=structuredClone(state);next.library=addFolder(next.library,$('newFolderTitle').value,!libAtRoot&&$('isSubfolder').checked?$('libraryFolder').value:null);const id=next.library.at(-1).id;if(countUploads())throw Error('Guarda o descarta la selección antes de crear una carpeta.');await commit(next);libAtRoot=false;libKind='all';$('libraryFolder').value=id;$('newFolderTitle').value='';$('librarySearch').value='';$('isSubfolder').checked=true;$('libManage').open=false;renderLibrary();renderReuse();status('Carpeta guardada.')});

$('libraryFiles').onclick=run(async ev=>{const b=ev.target.closest('button');if(!b)return;const folder=state.library.find(f=>f.id===$('libraryFolder').value);if(b.dataset.libget!==undefined){const f=folder.files[+b.dataset.libget];fileDownload(f.name,f.data)}else if(b.dataset.libmove!==undefined){const next=structuredClone(state);next.library=moveFile(next.library,folder.id,+b.dataset.libmove,b.closest('.lib-file').querySelector('[data-movetarget]').value);await commit(next);renderReuse();status('Archivo movido.')}else if(b.dataset.libdel!==undefined&&confirm('¿Quitar este archivo del repositorio? Las pruebas que ya lo utilizan conservan su copia.')){const next=structuredClone(state);next.library.find(f=>f.id===folder.id).files.splice(+b.dataset.libdel,1);await commit(next);renderReuse();status('Archivo eliminado del repositorio.')}});
function renderLinked(){const files=materialManifest(draft), count=k=>files.filter(f=>f.kind===k).length;$('linkedSummary').textContent=`Vinculados: ${count('content')} contenidos · ${count('rubric')} rúbricas/criterios · ${count('solution')} solucionarios · ${count('model')} modelos · ${count('instructions')} instrucciones. ${draft.plan?'Guía validada; materiales fijos.':''}`;$('heldPdfInfo').hidden=!heldPdf;$('cancelHeld').hidden=!heldPdf;$('heldPdfInfo').textContent=heldPdf?'PDF escaneado seleccionado: '+heldPdf.name+'. Se abrirá al validar la prueba. Si cierras la app, tendrás que volver a elegirlo.':'';$('resumeScan').hidden=workflowMode==='correct'||!draft.plan;$('guidePack').disabled=!!draft.plan;$('creatorPack').disabled=!!draft.plan;}
function isDescendant(id,root){while(id){if(id===root)return true;id=state.library.find(f=>f.id===id)?.parentId;}return false;}
function selectGuideEntries(entries){reuseChoice.clear();for(const e of entries)reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});}
function selectionKey(e){return JSON.stringify([e.folderId,e.file.kind,e.file.name,e.index]);}
function refreshSelection(){const all=state.library.flatMap(f=>f.files.map((file,index)=>({file,index,folderId:f.id,path:folderPath(state.library,f.id)})));const map=new Map(all.map(e=>[selectionKey(e),e]));for(const [k,v] of reuseChoice){if(!map.has(k)||map.get(k).file.data!==v.data)reuseChoice.delete(k);}return all;}
function updateBasket(){const entries=[...reuseChoice.values()];$('reuseCount').textContent=entries.length+' documentos seleccionados en todas las carpetas';$('reuseBasketList').replaceChildren(...entries.map(f=>{const p=document.createElement('p');p.textContent=(materialLabels[f.kind]||f.kind)+' · '+f.name+' — '+f.sourcePath;return p}));if(draft&&workflowMode==='correct')renderReadiness();}
function renderReuse(){const select=$('reuseFolder'),old=select.value;select.replaceChildren(new Option('Todos los temas y PAU',''),...state.library.slice().sort((a,b)=>folderPath(state.library,a.id).localeCompare(folderPath(state.library,b.id),'es',{numeric:true})).map(f=>new Option(folderPath(state.library,f.id),f.id)));if(state.library.some(f=>f.id===old))select.value=old;const list=$('reuseList');list.replaceChildren();const locked=!!draft?.plan;if(reuseDraftId!==draft?.id){reuseDraftId=draft?.id;reuseChoice.clear();if(uploadLocation!=='library'){$('referenceFolderName').value=draft?.title?.slice(0,100)||'';$('referenceFolder').value='';$('referenceFiles').value='';$('referenceText').value='';}}const all=refreshSelection();const linked=materialManifest(draft||{});if(!reuseChoice.size&&linked.length&&!locked&&!draft._selectionInitialized){for(const e of all){if(linked.some(f=>f.kind===e.file.kind&&f.data===e.file.data&&(f.name===e.file.name||f.name.endsWith(' — '+e.file.name))))reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});}draft._selectionInitialized=true;}for(const id of ['reuseFiles','replaceLinked','reuseAll','reuseNone'])$(id).disabled=locked;const entries=(select.value?folderMaterials(state.library,select.value,$('reusePAU').checked):all).filter(e=>workflowMode==='correct'||e.file.kind!=='guide');for(const kind of Object.keys(materialLabels)){const matching=entries.filter(e=>e.file.kind===kind);if(!matching.length)continue;const div=document.createElement('div');div.className='item';const h=document.createElement('strong');h.textContent=(repositoryKinds.materials.includes(kind)?'Materiales · ':'Corrección · ')+materialLabels[kind];div.append(h);for(const e of matching){const {file:f,path}=e,l=document.createElement('label'),c=document.createElement('input'),key=selectionKey(e);l.className='check';c.type='checkbox';c.disabled=locked||!!(draft?.createdPages&&f.kind==='model');c.checked=reuseChoice.has(key);c._key=key;c._material={...f,sourcePath:path};c.onchange=()=>{if(c.checked){if(f.kind==='guide'){for(const [k,v] of reuseChoice)if(repositoryKinds.correction.includes(v.kind))reuseChoice.delete(k);const matches=resolveGuideEntries(state.library,e.folderId,correctionType(draft),e);if(matches)selectGuideEntries(matches);else reuseChoice.set(key,c._material);renderReuse();return;}if(repositoryKinds.correction.includes(f.kind)&&[...reuseChoice.values()].some(v=>v.kind==='guide')){c.checked=false;status('La guía única ya incluye estos documentos. Desmárcala si quieres utilizar referencias antiguas.',true);return;}reuseChoice.set(key,c._material);}else reuseChoice.delete(key);updateBasket()};l.append(c,document.createTextNode(f.name+' · '+path));div.append(l)}list.append(div)}if(!list.children.length)list.textContent=select.value?'No hay archivos en esta carpeta ni sus subcarpetas.':'Elige una carpeta del repositorio para ver sus documentos.';updateBasket();}
$('reuseFolder').onchange=()=>{if(workflowMode==='correct'&&!draft.plan&&$('reuseFolder').value){const id=$('reuseFolder').value;draft.referenceFolderId=id;const matches=resolveGuideEntries(state.library,id,correctionType(draft));if(matches){selectGuideEntries(matches);}else if(!reuseChoice.size){const entries=folderMaterials(state.library,id);for(const k of requiredRoles(draft)){const m=entries.filter(e=>e.file.kind===k);if(m.length===1){const e=m[0];reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});}}}}renderReuse();};$('reusePAU').onchange=renderReuse;
$('reuseAll').onclick=()=>{const cs=[...$('reuseList').querySelectorAll('input:not(:disabled)')];const guides=cs.filter(c=>c._material.kind==='guide');for(const c of cs){if(guides.length&&repositoryKinds.correction.includes(c._material.kind))continue;c.checked=true;reuseChoice.set(c._key,c._material)}if(guides.length===1){const c=guides[0];for(const [k,v] of reuseChoice)if(repositoryKinds.correction.includes(v.kind))reuseChoice.delete(k);c.checked=true;reuseChoice.set(c._key,c._material);renderReuse()}else updateBasket();if(guides.length>1)status('Elige una sola guía de corrección para esta prueba.');};$('reuseNone').onclick=()=>{reuseChoice.clear();for(const c of $('reuseList').querySelectorAll('input'))c.checked=false;updateBasket()};
async function applySelectedMaterials(){if(draft.plan)throw Error('Prueba bloqueada.');refreshSelection();const entries=[...reuseChoice.values()];if(!entries.length&&workflowMode!=='correct')throw Error('Selecciona al menos un archivo en la biblioteca.');const replace=workflowMode==='create'||$('replaceLinked').checked;const base=replace?Object.fromEntries(Object.entries(draft.materials).map(([k,files])=>[k,files.filter(f=>!f.sourcePath||(k==='model'&&draft.createdPages))])):draft.materials;const cleanBase=entries.some(f=>f.kind==='guide')?{...base,rubric:[]}:base;const nextMaterials=attachMaterials(cleanBase,entries,{skipModel:!!draft.createdPages});if(!draft.createdPages&&workflowMode==='create'){const images=new Map();for(const f of materialManifest({materials:nextMaterials})){if(!/^data:image\/(?:png|jpeg|webp);base64,/.test(f.data))continue;if(images.has(f.name)&&images.get(f.name)!==f.data)throw Error('Dos imágenes distintas se llaman '+f.name+'. Selecciona solo una o renombra el archivo en tu dispositivo.');images.set(f.name,f.data)}const previousFigures=structuredClone(figures);try{if(replace)figures=Object.create(null);for(const f of entries){const mime=/^data:(image\/(?:png|jpeg|webp));base64,/.exec(f.data)?.[1];if(mime)await addFigure(new File([dataBytes(f.data)],f.name,{type:mime}));}}catch(err){figures=previousFigures;throw err}}draft.materials=nextMaterials;draft.workflowMode=workflowMode;if(workflowMode==='correct'&&$('reuseFolder').value)draft.referenceFolderId=$('reuseFolder').value;$('replaceLinked').checked=workflowMode==='correct';draft.title=$('title').value.trim()||state.library.find(f=>f.id===$('reuseFolder').value)?.title||'Nueva prueba';renderDraft();await saveDraft(false);$('reusePanel').open=false;if(workflowMode==='correct'){$('creatorPanel').open=false;try{ensureMaterials();await enterCorrection();}catch(err){$('reusePanel').open=true;status('Material guardado. '+err.message,true);return;}}else $('creatorPanel').open=true;if(workflowMode!=='correct')status('Material vinculado y guardado. No es necesario volver a subirlo.');}
$('reuseFiles').onclick=run(applySelectedMaterials);
for(const id of Object.values(numberFields))$(id).oninput=()=>{invalidateCreator();updateCodePreview()};
$('creatorJson').oninput=()=>{$('questionEditor').replaceChildren();editorDirty=false;invalidateCreator()};$('creatorJsonFile').onchange=run(async e=>{try{if(e.target.files[0]){const raw=parseJSON(await e.target.files[0].text());if(raw.type?.startsWith('auto-ger-creation-'))await importCreation(raw);else{$('creatorJson').value=JSON.stringify(raw,null,2);delete draft.generatedBundle;$('questionEditor').replaceChildren();editorDirty=false;invalidateCreator();showBundle()}}}finally{e.target.value=''}});
function creatorReady(){draft.title=$('title').value.trim();if(!draft.title||!hasCreationSource(draft))throw Error('Añade un título y selecciona contenidos o modelos del repositorio de temas o PAU. No necesitas una rúbrica previa para generar una propuesta nueva.');}
function newCreationPrompt(){return creationBundlePrompt(draft,$('creatorInstructions').value,$('creatorFormat').value,$('creationDifficulty').value,Array.from(document.querySelectorAll('[data-creation-type]'),e=>e.value));}
async function importCreation(raw){creatorReady();const b=validateCreationBundle(raw,draft,$('creatorFormat').value);draft.generatedBundle=b;$('creatorJson').value=JSON.stringify(b.exam,null,2);$('questionEditor').replaceChildren();editorDirty=false;invalidateCreator();showBundle();await saveDraft(false);status('Propuesta, rúbrica y solucionario importados. Revisa los tres antes de generar la muestra.');}
function showBundle(){const b=draft?.generatedBundle;const el=$('creationBundleReview');el.replaceChildren();if(!b)return;const h=document.createElement('p');h.textContent='Propuesta importada: '+b.exam.questions.length+' cuestiones. Revisa las referencias antes de aprobar.';el.append(h);for(const d of bundleDocuments(b)){const detail=document.createElement('details'),sum=document.createElement('summary'),pre=document.createElement('pre');sum.textContent=d.name;pre.textContent=d.text;pre.style.whiteSpace='pre-wrap';detail.append(sum,pre);el.append(detail)}}
$('copyCreator').onclick=run(async()=>{if(reuseChoice.size)await applySelectedMaterials();else if(materialManifest(draft).some(f=>f.sourcePath))throw Error('Selecciona los archivos del repositorio que quieres utilizar.');creatorReady();await saveDraft(false);await copy(newCreationPrompt(),'instrucciones-creacion.txt')});
$('creatorMaterials').onclick=run(()=>{creatorReady();const out=$('creatorDownloads');out.replaceChildren();for(const k of ['model','content','rubric'])for(const f of draft.materials[k]){const b=document.createElement('button');b.className='secondary';b.textContent=f.name+' ↓';b.onclick=()=>{if(!busy&&ready)fileDownload(f.name,f.data)};out.append(b)}});
async function addFigure(file){if(!file.size||file.size>20*1024*1024)throw Error('Imagen vacía o de más de 20 MB.');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas'),factor=Math.min(1,2400/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.max(1,Math.round(img.naturalWidth*factor));c.height=Math.max(1,Math.round(img.naturalHeight*factor));const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);figures[file.name]={data:c.toDataURL('image/jpeg',.94),width:c.width,height:c.height};c.width=c.height=0}finally{URL.revokeObjectURL(url)}}
function showFigures(){$('figureList').textContent=Object.keys(figures).join(' · ');invalidateCreator()}

function decodeFigures(f){return Object.fromEntries(Object.entries(f||{}).map(([k,v])=>[k,{width:v.width,height:v.height,bytes:dataBytes(v.data)}]))}
function layoutFor(model,fig){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');return layoutExam(model,fig,(text,size,bold)=>{ctx.font=`${bold?'bold ':''}${size}px Arial`;return ctx.measureText(text).width*1.04})}
async function checkCreator(){creatorReady();const n=readNumbering();if(state.exams.some(e=>e.id!==draft.id&&e.numbering&&prefix(e.numbering)===prefix(n)))throw Error('Ya existe una prueba con este tema, materia, grupo y número de prueba escrita. Elige otro número.');if($('creatorMode').value==='existing'){if($('creatorFormat').value==='pau')throw Error('Para validar automáticamente el formato PAU, usa Crear/adaptar con editor. Para reproducir un PDF existente, selecciona PAU adaptable.');if($('existingSource').value==='')throw Error('Selecciona un PDF de examen existente.');if(!confirm('El PDF existente se reproduce como imagen. Comprueba que no contiene avisos de puntuación decimal; si los contiene, adapta el examen en el editor. ¿Continuar?'))throw Error('Reproducción cancelada.');const file=draft.materials.model[+$('existingSource').value];if(!file)throw Error('PDF no seleccionado.');const scan=await openScan(new File([dataBytes(file.data)],file.name,{type:'application/pdf'}));const figData=Object.create(null);try{if(scan.count>20)throw Error('Máximo 20 páginas por examen existente.');for(let i=1;i<=scan.count;i++){const page=await scan.page(i),url=URL.createObjectURL(page),img=new Image();try{img.src=url;await img.decode();figData['original-'+String(i).padStart(2,'0')+'.jpg']={width:img.naturalWidth,height:img.naturalHeight,data:await read(page)}}finally{URL.revokeObjectURL(url)}}}finally{await scan.close()}const fig=decodeFigures(figData),pages=layoutExisting(fig);return {n,model:null,fig,figData,pages,source:file.data,mode:'existing',originalName:file.name}}if(editorDirty)throw Error('Pulsa Aplicar preguntas antes de generar la muestra.');const parsed=parseJSON($('creatorJson').value);const model=$('creatorFormat').value==='pau'?validatePauExam(parsed):validatePauCustomExam(parsed);if(model.questions.some(q=>/\[(?:Pregunta|Cinco conceptos|Localizaciones|Explicación|Noticia)/i.test(q.text)))throw Error('Completa los marcadores de la plantilla.');model.title=draft.title;if(draft.generatedBundle){const b=validateCreationBundle(draft.generatedBundle,draft,$('creatorFormat').value);if(JSON.stringify(model.questions)!==JSON.stringify(b.exam.questions)||model.instructions!==b.exam.instructions)throw Error('Has cambiado la propuesta. Solicita otra propuesta con rúbrica y solucionario actualizados antes de imprimir.');}else if(!hasRubric(draft.materials))throw Error('Para una propuesta manual necesitas una rúbrica existente o importar la propuesta completa de ChatGPT.');const fig=decodeFigures(figures),pages=layoutFor(model,fig);return {n,model,fig,figData:structuredClone(figures),pages,source:$('creatorJson').value,mode:'new'}}
