$('applyRanges').onclick=run(()=>{if(!batch)throw Error('Abre un PDF primero.');if(noCodeBatch())return setBatchRanges(parsePageGroups($('ranges').value,batch.count));const r=$('ranges').value.trim().split(/\r?\n/).filter(s=>s.trim()).map((s,i)=>{if(noCodeBatch()){const m=s.match(/^\s*(?:\d+\s*:\s*)?(\d+)\s*(?:-\s*(\d+))?\s*$/);if(!m)throw Error('Usa inicio-fin, o una sola página, por línea.');return {student:i+1,start:+m[1],end:+(m[2]||m[1])}}const m=s.match(/^\s*(\d+)\s*:\s*(\d+)\s*-\s*(\d+)\s*$/);if(!m)throw Error('Usa el formato alumno: inicio-fin, una línea por alumno.');return {student:+m[1],start:+m[2],end:+m[3]}});return setBatchRanges(r)});
