async function renderVisualPages(){if(!batch||!noCodeBatch())throw Error('Selecciona el modo flexible.');const host=$('visualPages');host.replaceChildren();$('visualPosition').textContent=`Páginas ${visualStart}–${Math.min(batch.count,visualStart+11)} de ${batch.count}`;$('visualPrev').disabled=visualStart===1;$('visualNext').disabled=visualStart+12>batch.count;for(let n=visualStart;n<=Math.min(batch.count,visualStart+11);n++){const file=await batch.page(n),url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const canvas=document.createElement('canvas'),scale=Math.min(1,420/img.naturalWidth);canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const card=document.createElement('div');card.className='page-thumb';const label=document.createElement('strong');label.textContent='Página original '+n;const preview=document.createElement('img');preview.src=canvas.toDataURL('image/jpeg',.9);preview.alt='Vista de página '+n;canvas.width=canvas.height=0;const zoom=document.createElement('button');zoom.className='secondary';zoom.textContent='Ampliar hoja';zoom.onclick=run(async()=>{const f=await batch.page(n),src=URL.createObjectURL(f);const dialog=document.createElement('dialog');dialog.className='visual-dialog';const close=document.createElement('button');close.textContent='Cerrar vista';close.onclick=()=>dialog.close();const large=document.createElement('img');large.alt='Página original '+n;large.src=src;dialog.append(close,large);document.body.append(dialog);dialog.addEventListener('close',()=>{URL.revokeObjectURL(src);dialog.remove()},{once:true});dialog.showModal();});const controls=document.createElement('div');const l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.checked=n===1||visualCuts.has(n);c.disabled=n===1;c.onchange=()=>{if(c.checked)visualCuts.add(n);else visualCuts.delete(n);visualCount()};l.className='check';l.append(c,' Nuevo examen aquí');const groupLabel=document.createElement('label');groupLabel.textContent='Grupo de esta hoja (opcional)';const group=document.createElement('input');group.type='number';group.min=1;group.max=99;group.step=1;group.placeholder='Ej.: 2';group.value=visualAssignments.get(n)||'';group.oninput=()=>{if(group.value&&Number.isInteger(+group.value)&&+group.value>=1&&+group.value<=99)visualAssignments.set(n,+group.value);else visualAssignments.delete(n);visualCount();};groupLabel.append(group);controls.append(l,groupLabel);card.append(label,preview,zoom,controls);host.append(card);}finally{URL.revokeObjectURL(url)}}visualCount();}
