let uploadLocation='prepare';
function countUploads(){return $('referenceFiles').files.length+($('referenceText').value.trim()?1:0)}
function placeUpload(id){if(id!=='library'&&id!=='prepare')return true;const target=id==='library'?'library':'prepare';if(target!==uploadLocation&&countUploads()){if(!confirm('Hay material sin guardar. ¿Descartarlo para cambiar de pantalla?'))return false;$('referenceFiles').value='';$('referenceText').value='';}uploadLocation=target;$(target==='library'?'quickLibrary':'prepareUploadSlot').append($('missingUploadPanel'));$('referenceSave').textContent=target==='library'?'Guardar en el repositorio':'Guardar en repositorio y vincular';$('missingUploadPanel').querySelector('h3').textContent=target==='library'?'Añadir documentos':'Añadir material al repositorio y vincular';$('referenceFolderBox').hidden=target==='library';$('missingUploadPanel').hidden=target==='prepare'&&(!!draft?.plan||guideMode);if(target==='library'){const selected=$('referenceKind').value;const allowed=repositoryKinds[libraryView];$('referenceKind').replaceChildren(...allowed.map(k=>new Option(materialLabels[k],k)));$('referenceKind').value=allowed.includes(selected)?selected:allowed[0];}else if(draft)renderReadiness();return true;}
async function startFromRepository(mode,folder=null,file=null){if(countUploads()){status('Guarda o descarta los archivos seleccionados antes de iniciar una prueba.',true);return false;}if(mode==='correct'){await createCorrection(folder?state.library.find(f=>f.id===folder)?.title||'':'',file,folder);return true;}if((draft?.title||materialManifest(draft).length)&&!confirm('¿Preparar una nueva prueba? Los cambios no guardados se descartan.'))return false;flowId=null;guideMode=false;workflowMode='create';heldPdf=null;draft=fresh();draft.workflowMode='create';draft.title=folder?state.library.find(f=>f.id===folder)?.title||'':'';figures=Object.create(null);creatorDraftId=null;editorDirty=false;checkedCreation=null;renderDraft();if(folder)$('reuseFolder').value=folder;$('reusePAU').checked=false;renderReuse();if(folder&&folder!=='pau'){for(const e of folderMaterials(state.library,folder))if(e.file.kind==='content'||e.file.kind==='model')reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});renderReuse();}$('reusePanel').open=true;$('creatorPanel').open=true;$('attachedPanel').open=false;go('prepare');return true}
$('libraryCreate').onclick=run(()=>startFromRepository('create',$('libraryFolder').value));$('libraryCorrect').onclick=run(()=>startFromRepository('correct',$('libraryFolder').value));$('newScanExam').onclick=run(()=>go('work'));
async function activateScan(id){const activeExam=state.exams.find(e=>e.id===id);if(activeExam?.correctionType&&missingRoles(activeExam).length)throw Error('Faltan referencias obligatorias. Regresa al paso 2.');if((photos.length||batch)&&scanExam!==id){if(!confirm('¿Cerrar el escaneo anterior y descartar páginas sin guardar?'))return;clearPhotos();closeBatch()}flowId=id;guideMode=false;$('active').value=id;scanExam=id;renderAssignedCode();go('scan');const exam=state.exams.find(e=>e.id===id);if(exam?.scanSource&&!batch){await openBatchFile(sourceFile(exam.scanSource));}else if(heldPdf){const file=heldPdf;if(await openBatchFile(file)){heldPdf=null;renderLinked();}}}
