function validateScanSource(src){if(!src||typeof src.name!=='string'||!src.name||!Number.isInteger(src.count)||src.count<1||src.count>500||!/^([a-f0-9]{64})$/.test(src.hash))throw Error('Documento asociado inválido.');if(src.kind==='images'){if(!Array.isArray(src.images)||src.images.length!==src.count||src.count>100||src.images.some(f=>typeof f.name!=='string'||!/^data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+$/.test(f.data))||src.images.reduce((n,f)=>n+f.data.length,0)>140000000)throw Error('Fotografías asociadas inválidas.');}else if(typeof src.data!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/=]+$/.test(src.data)||src.data.length>140000000)throw Error('PDF asociado inválido.');return src;}
function sourceFile(src){validateScanSource(src);return src.kind==='images'?src:new File([dataBytes(src.data)],src.name,{type:'application/pdf'});}
async function openSource(file){if(file?.kind!=='images')return openScan(file);validateScanSource(file);return {count:file.count,hash:file.hash,close:()=>{},async page(i){const f=file.images[i-1];if(!f)throw Error('Página no encontrada.');return new File([dataBytes(f.data)],f.name,{type:/^data:([^;]+)/.exec(f.data)[1]});}}}
async function inspectSource(file){if(file?.kind==='images')return validateScanSource(file);if(!file||!file.size||file.size>100*1024*1024)throw Error('Elige un PDF válido de hasta 100 MB.');let opened;try{opened=await openScan(file);await opened.page(1);return validateScanSource({name:file.name,count:opened.count,hash:opened.hash,data:await read(file)});}finally{if(opened)await opened.close();}}
function renderWork(){const target=$('workTarget'),oldTarget=target.value;target.replaceChildren(new Option('Nueva prueba (examen ya realizado)',''),...state.exams.map(e=>new Option(e.title,e.id)));target.value=state.exams.some(e=>e.id===oldTarget)?oldTarget:'';const sel=$('workExam'),old=sel.value;sel.replaceChildren(new Option('Selecciona una prueba guardada',''),...state.exams.map(e=>new Option(e.title+(e.plan?' · guía validada':' · borrador'),e.id)));sel.value=state.exams.some(e=>e.id===old)?old:'';renderWorkSummary();}
