$('referenceClear').onclick=()=>{$('referenceFiles').value='';$('referenceText').value='';status('Selección descartada. Los materiales guardados se conservan.');};
$('referenceSave').onclick=run(async()=>{if(uploadLocation==='prepare'&&(!draft||draft.plan))throw Error('La guía ya está validada.');const kind=$('referenceKind').value;const entries=[];for(const f of $('referenceFiles').files){if(!f.size||f.size>100*1024*1024)throw Error('Archivo vacío o superior a 100 MB.');entries.push({kind,name:f.name,data:await read(f)});}const text=$('referenceText').value.trim();if(text){const name=(materialLabels[kind]||kind)+'.txt';entries.push({kind,name,data:await read(new File([text],name,{type:'text/plain'}))});}if(!entries.length)throw Error('Selecciona un archivo o escribe el texto.');if(kind==='guide'){if(entries.length!==1)throw Error('Añade una guía única cada vez.');guideDocument(entries[0].data);}const next=structuredClone(state),a=archiveReferenceFiles(next.library,uploadLocation==='library'?$('libraryFolder').value:($('referenceFolder').value||null),$('referenceFolderName').value.trim()||draft?.title,entries);next.library=a.library;await commit(next);$('referenceFiles').value='';$('referenceText').value='';if(uploadLocation==='library'){renderReuse();status('Material guardado en el repositorio.');return;}const all=refreshSelection();if(kind==='guide')for(const [k,v] of reuseChoice)if(repositoryKinds.correction.includes(v.kind))reuseChoice.delete(k);for(const e of all){if(e.folderId===a.folderId&&a.entries.some(f=>f.kind===e.file.kind&&f.name===e.file.name&&f.data===e.file.data))reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});}if(kind==='guide'&&workflowMode==='correct'){const g=all.find(e=>e.folderId===a.folderId&&e.file.kind==='guide'&&e.file.data===entries[0].data);const matches=g&&resolveGuideEntries(state.library,a.folderId,correctionType(draft),g);if(matches)selectGuideEntries(matches);draft.referenceFolderId=a.folderId;}draft.materials=prospectiveMaterials();if(workflowMode==='create'&&!draft.createdPages){for(const f of a.entries){const mime=/^data:(image\/(?:png|jpeg|webp));base64,/.exec(f.data)?.[1];if(mime)await addFigure(new File([dataBytes(f.data)],f.name,{type:mime}));}showFigures();}if($('title').value.trim())await saveDraft(false);$('referenceFiles').value='';$('referenceText').value='';$('referenceFolder').value=a.folderId;renderReuse();renderLinked();renderReadiness();const missing=missingRoles({...draft,materials:prospectiveMaterials()});if(workflowMode==='correct'&&missing.length)$('referenceKind').value=missing[0];status('Material guardado en la biblioteca y vinculado. Puedes continuar cuando estén todos los obligatorios.');});

function renderFlow(id){$('active').disabled=!!flowId;$('active').hidden=!!flowId;$('activeLabel').hidden=!!flowId;const e=state.exams.find(x=>x.id===flowId),enabled=id==='work'||!!e&&['prepare','scan','queue','grades'].includes(id);$('flowHeader').hidden=!enabled;$('scanFlowActions').hidden=!e;$('resultsFlowActions').hidden=!(e&&id==='grades');if(!enabled)return;const stage=id==='work'?1:id==='prepare'?(guideMode?3:2):id==='grades'?4:3;$('flowTitle').textContent=e?e.title:'Nueva corrección';const pending=e?state.pending.filter(r=>r.examId===e.id).length:0,done=e?state.records.filter(r=>r.examId===e.id).length:0;$('scanToQueue').disabled=!pending;$('scanToResults').disabled=!done;$('queueResults').disabled=!done;$('flowProgress').textContent=e?`${e.scanSource?e.scanSource.count+' páginas guardadas':'Sin documento asociado'} · ${materialManifest(e).length} materiales · ${pending} pendientes · ${done} validados`:'Selecciona el documento de los alumnos para empezar.';for(const b of $('flowHeader').querySelectorAll('[data-stage]')){const n=+b.dataset.stage;b.setAttribute('aria-current',n===stage?'step':'false');b.disabled=n!==1&&(!e||n===3&&!e.plan&&n>stage||n===4&&!done);}}
async function enterCorrection(){if(!draft.plan){ensureMaterials();const storedPlan=planFromRepository(draft);if(storedPlan){const locked=structuredClone(draft);locked.plan=storedPlan;const next=structuredClone(state),i=next.exams.findIndex(e=>e.id===locked.id);if(i<0)next.exams.push(locked);else next.exams[i]=locked;await commit(next);draft=structuredClone(locked);renderDraft();await activateScan(locked.id);status('Guía única del repositorio aplicada. Puedes corregir sin preparar otra guía.');return;}await saveDraft();guideMode=true;renderWorkDraft();go('prepare');showRepositoryPlan();}else await activateScan(draft.id);}
function loadMaterials(id){guideMode=false;loadCorrection(id);$('replaceLinked').checked=true;if(draft.referenceFolderId&&state.library.some(f=>f.id===draft.referenceFolderId)){ $('reuseFolder').value=draft.referenceFolderId;if(!draft.plan&&!materialManifest(draft).length){const entries=folderMaterials(state.library,draft.referenceFolderId);const gs=entries.filter(e=>e.file.kind==='guide');const match=resolveGuideEntries(state.library,draft.referenceFolderId,correctionType(draft));if(match){selectGuideEntries(match);}else for(const k of requiredRoles(draft)){const matches=entries.filter(e=>e.file.kind===k);if(matches.length===1){const e=matches[0];reuseChoice.set(selectionKey(e),{...e.file,sourcePath:e.path});}}}renderReuse();}renderWorkDraft();go('prepare');}
async function resumeCorrection(id){loadMaterials(id);const e=state.exams.find(x=>x.id===id);if(!e.scanSource&&!state.pending.some(r=>r.examId===id)&&!state.records.some(r=>r.examId===id)){go('work');$('workTarget').value=id;status('Selecciona el PDF o fotografías de esta prueba.');return;}if(e.plan){if(state.pending.some(r=>r.examId===id))go('queue');else if(e.scanSource)await activateScan(id);else go('grades');}else if(materialManifest(e).length){$('reusePanel').open=true;}}
async function createCorrection(title,file,folder,type='exam'){if((photos.length||batch)&&!confirm('¿Cerrar el escaneo anterior? Los exámenes ya guardados se conservan.'))return;if(draft?.title&&!state.exams.some(e=>e.id===draft.id)&&!confirm('¿Descartar el borrador anterior sin guardar?'))return;const src=file?await inspectSource(file):null;title=title.trim()||(file?file.name.replace(/\.pdf$/i,''):'Nueva corrección');const e=fresh();e.title=title;e.workflowMode='correct';e.correctionType=type;if(folder)e.referenceFolderId=folder;if(src)e.scanSource=src;const next=structuredClone(state);next.exams.push(e);await commit(next);clearPhotos();closeBatch();scanExam='';$('active').value='';draft=structuredClone(e);workflowMode='correct';flowId=e.id;guideMode=false;heldPdf=null;figures=Object.create(null);creatorDraftId=null;editorDirty=false;checkedCreation=null;renderDraft();$('reuseFolder').value=folder||'';$('reusePAU').checked=false;renderReuse();$('reusePanel').open=true;$('attachedPanel').open=false;$('replaceLinked').checked=true;if(src){go('prepare');if(folder)$('reuseFolder').onchange();}else{go('work');$('workTarget').value=e.id;$('workType').value=correctionType(e);$('workType').disabled=false;}status('Prueba guardada'+(src?' con documento asociado':'')+'. '+(src?'Selecciona los materiales.':'Selecciona primero el documento escaneado.'));return true;}
async function saveSource(id,file,type){const e=state.exams.find(e=>e.id===id);if(!e)throw Error('Guarda la prueba antes de asociar el PDF.');const src=await inspectSource(file);if(e.scanSource&&e.scanSource.hash!==src.hash&&!confirm('¿Sustituir el PDF asociado a '+e.title+'? Los exámenes ya guardados no se modifican.'))throw Error('Se ha conservado el PDF anterior.');const next=structuredClone(state);const item=next.exams.find(e=>e.id===id);if(item.scanSource?.hash!==src.hash)delete item.scanConfig;item.scanSource=src;if(type&&!item.plan&&!item.numbering)item.correctionType=type;await commit(next);if(draft?.id===id){draft.scanSource=src;if(draft.scanConfig?.hash!==src.hash)delete draft.scanConfig;renderWorkDraft();}status('PDF guardado en la prueba '+e.title+'.');return src;}
function loadCorrection(id){const e=state.exams.find(e=>e.id===id);if(!e)throw Error('Selecciona una prueba.');draft=structuredClone(e);delete draft._selectionInitialized;reuseChoice.clear();reuseDraftId=null;if(!draft.plan)draft.correctionType=correctionType(draft);draft.workflowMode='correct';workflowMode='correct';flowId=id;heldPdf=null;figures=structuredClone(e.creator?.figures||{});creatorDraftId=null;editorDirty=!!e.creator?.editorDirty;checkedCreation=null;renderDraft();$('reusePanel').open=!e.plan;$('creatorPanel').open=false;go('prepare');}
$('workExam').onchange=renderWorkSummary;
function renderWorkPhotos(){$('workImageList').replaceChildren(...workPhotos.map((f,i)=>{const div=document.createElement('div');div.className='source-photo';const t=document.createElement('span');t.textContent=`${i+1}. ${f.name}`;div.append(t);for(const [op,label] of [['up','↑'],['down','↓'],['remove','Quitar']]){const b=document.createElement('button');b.className='secondary';b.textContent=label;b.dataset.photoOp=op;b.dataset.index=i;b.disabled=op==='up'&&i===0||op==='down'&&i===workPhotos.length-1;b.setAttribute('aria-label',`${op==='up'?'Subir':op==='down'?'Bajar':'Quitar'} página ${i+1}`);div.append(b)}return div}));$('workImageClear').hidden=!workPhotos.length;}
for(const id of ['workCamera','workImages'])$(id).onchange=run(async ev=>{try{const files=[...ev.target.files];if(!files.length)return;if(workPhotos.length+files.length>100||[...workPhotos,...files].reduce((n,f)=>n+f.size,0)>100*1024*1024)throw Error('Máximo 100 fotografías y 100 MB.');for(const f of files){if(!f.type.startsWith('image/')||!f.size)throw Error('Selecciona imágenes válidas.');const u=URL.createObjectURL(f);try{const img=new Image();img.src=u;await img.decode()}finally{URL.revokeObjectURL(u)}}workPhotos.push(...files);renderWorkPhotos();}finally{ev.target.value=''}});
$('workImageList').onclick=run(ev=>{const b=ev.target.closest('[data-photo-op]');if(!b)return;const i=+b.dataset.index,op=b.dataset.photoOp;if(op==='remove')workPhotos.splice(i,1);else{const j=i+(op==='up'?-1:1);if(j>=0&&j<workPhotos.length)[workPhotos[i],workPhotos[j]]=[workPhotos[j],workPhotos[i]];}renderWorkPhotos();});$('workImageClear').onclick=run(()=>{workPhotos=[];renderWorkPhotos()});
async function capturedSource(){if(!workPhotos.length)return null;const images=[];for(const f of workPhotos)images.push({name:f.name,data:await read(f)});const hashes=[];for(const f of workPhotos)hashes.push(Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join(''));const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(hashes.join(':')))),b=>b.toString(16).padStart(2,'0')).join('');return validateScanSource({kind:'images',name:'Escaneo fotográfico',count:images.length,images,hash});}
$('workTarget').onchange=()=>{const e=state.exams.find(e=>e.id===$('workTarget').value);$('workTitle').disabled=!!e;$('workType').disabled=!!e&&(!!e.plan||!!e.numbering);if(e){$('workTitle').value=e.title;$('workType').value=correctionType(e);}else $('workTitle').value='';};
$('workStart').onclick=run(async()=>{const id=$('workTarget').value,file=$('workPdf').files[0];if(file&&workPhotos.length)throw Error('Elige PDF o fotografías, no ambos.');const source=file||await capturedSource();if(!source)throw Error('Selecciona un PDF o añade fotografías antes de continuar.');if(id){if((photos.length||batch)&&!confirm('¿Cerrar las páginas abiertas sin guardar?'))return;await saveSource(id,source,$('workType').value);clearPhotos();closeBatch();loadMaterials(id);if(draft.plan)await activateScan(id);else if(draft.referenceFolderId){$('reuseFolder').value=draft.referenceFolderId;$('reuseFolder').onchange();}}else if(!await createCorrection($('workTitle').value,source,null,$('workType').value))return;$('workPdf').value='';$('workTitle').value='';$('workTitle').disabled=false;$('workType').disabled=false;workPhotos=[];renderWorkPhotos();});
$('workResume').onclick=run(()=>resumeCorrection($('workExam').value));
$('materialsNext').onclick=run(async()=>{if(!draft.plan&&(reuseChoice.size||$('replaceLinked').checked&&materialManifest(draft).some(f=>f.sourcePath)))await applySelectedMaterials();else await enterCorrection()});
$('guideBack').onclick=run(()=>loadMaterials(draft.id));
$('scanToQueue').onclick=run(()=>{if(photos.length)throw Error('Guarda o descarta las páginas abiertas antes de continuar.');go('queue');const first=state.pending.find(r=>r.examId===flowId);if(first)openPending(first.code);});
$('scanToResults').onclick=run(()=>go('grades'));$('queueResults').onclick=run(()=>go('grades'));$('resultContinue').onclick=run(()=>go('queue'));$('resultPages').onclick=run(()=>activateScan(flowId));
$('flowHeader').onclick=run(async ev=>{const b=ev.target.closest('[data-stage]');if(!b)return;const n=+b.dataset.stage;if(n===1){go('work');if(flowId)$('workTarget').value=flowId;return;}if(!flowId)return;if(n===2){loadMaterials(flowId);return;}if(n===3){if(guideMode&&draft?.id===flowId&&!draft.plan){go('prepare');return;}await resumeCorrection(flowId);return;}if(n===4)go('grades');});
$('sourceInput').onchange=run(async ev=>{try{if(!ev.target.files[0])return;if(!state.exams.some(e=>e.id===draft.id))await saveDraft(false);await saveSource(draft.id,ev.target.files[0]);}finally{ev.target.value=''}});
$('removeSource').onclick=run(async()=>{if(!confirm('¿Retirar el PDF original guardado? Los exámenes ya anonimizados se conservan.'))return;const next=structuredClone(state),e=next.exams.find(e=>e.id===draft.id);if(!e)return;delete e.scanSource;delete e.scanConfig;await commit(next);delete draft.scanSource;delete draft.scanConfig;renderWorkDraft();if(scanExam===draft.id&&batch){clearPhotos();closeBatch()}status('PDF original retirado.');});
$('reopenSource').onclick=run(async()=>{const e=state.exams.find(e=>e.id===$('active').value);if(!e?.scanSource)throw Error('No hay PDF asociado.');await openBatchFile(sourceFile(e.scanSource));});
$('scanBack').onclick=run(()=>loadMaterials($('active').value));$('prepBack').onclick=run(()=>{go('work');if(flowId)$('workTarget').value=flowId;});
// The dedicated create button always opens the generator, not the last correction draft.
for(const b of document.querySelectorAll('[data-go="prepare"]'))b.onclick=()=>{if(!ready||busy)return;flowId=null;guideMode=false;if(workflowMode==='correct'){draft=fresh();workflowMode='create';heldPdf=null;creatorDraftId=null;figures=Object.create(null);checkedCreation=null;editorDirty=false;renderDraft();}go('prepare')};

for(const el of document.querySelectorAll('[data-creation-type],#creationDifficulty'))el.onchange=invalidateCreator;

function switchRepository(which){if(countUploads()){status('Guarda o descarta los archivos antes de cambiar de repositorio.',true);return;}libraryView=which;libKind='all';$('librarySearch').value='';$('quickLibrary').open=false;$('unifiedPreparation').hidden=true;placeUpload('library');renderLibrary();}
$('repositoryMaterials').onclick=()=>switchRepository('materials');$('repositoryCorrection').onclick=()=>switchRepository('correction');$('pairedRepo').onclick=()=>switchRepository(libraryView==='materials'?'correction':'materials');
$('prepareUnified').onclick=run(()=>{const id=$('libraryFolder').value;const entries=folderMaterials(state.library,id);const models=entries.filter(e=>e.file.kind==='model');const contents=entries.filter(e=>e.file.kind==='content');if(!models.length)throw Error('Añade primero el examen o enunciado al repositorio de materiales.');$('unifiedPreparation').hidden=false;const model=$('unifiedModel');model.replaceChildren(...models.map((e,i)=>new Option(e.file.name+' · '+e.path,String(i))));const list=$('unifiedContents');list.replaceChildren();for(const e of contents){const l=document.createElement('label'),c=document.createElement('input');l.className='check';c.type='checkbox';c.checked=true;c._entry=e;l.append(c,document.createTextNode(e.file.name+' · '+e.path));list.append(l);}model._entries=models;$('unifiedPreparation').scrollIntoView({block:'start'});});
$('downloadUnified').onclick=run(()=>{const e=$('unifiedModel')._entries?.[+$('unifiedModel').value];if(!e)throw Error('Selecciona un enunciado.');const contents=[...$('unifiedContents').querySelectorAll('input:checked')].map(c=>c._entry.file);const type=$('unifiedType').value;if(type==='exam'&&!contents.length)throw Error('Selecciona al menos un contenido del tema.');const names=[e.file.name,...contents.map(f=>f.name)];if(new Set(names.map(n=>n.toLocaleLowerCase('es'))).size!==names.length||names.includes('00-instrucciones.txt'))throw Error('Hay nombres repetidos o reservados. Renombra los archivos en tu dispositivo para distinguirlos.');const material={materials:attachMaterials({content:[],model:[],rubric:[]},[e.file,...contents])};downloadPack(material,preparationPrompt(e.file.name,contents.map(f=>f.name),type),'preparar-guia-unica');});
$('openCorrectionRepo').onclick=()=>switchRepository('correction');
function showRepositoryPlan(){if(!materialManifest(draft).some(f=>f.kind==='guide'))return;proposed=planFromRepository(draft);showPlan(proposed);$('approve').checked=false;$('lock').disabled=true;status('Guía única recuperada del repositorio. Revisa y valida; no es necesario solicitar otro JSON.');}
